input.newString:
tree(W*.13,H*.25,.78,1);tree(W*.36,H*.22,.95);tree(W*.56,H*.28,.73,1);tree(W*.92,H*.69,.88);tree(W*.88,H*.22,.75,1);
}
function drawWoods(){// forest clearing and luminous stream
ctx.beginPath();ctx.moveTo(W*.57,H);ctx.bezierCurveTo(W*.42,H*.7,W*.72,H*.64,W*.57,H*.31);ctx.bezierCurveTo(W*.50,H*.12,W*.68,H*.04,W*.73,0);ctx.lineTo(W*.86,0);ctx.bezierCurveTo(W*.77,H*.25,W*.65,H*.26,W*.70,H*.48);ctx.bezierCurveTo(W*.80,H*.78,W*.56,H*.82,W*.72,H);ctx.closePath();ctx.fillStyle='#78b3ae';ctx.fill();ctx.strokeStyle='#b9e2d0';ctx.lineWidth=3;ctx.stroke();
for(let i=0;i<18;i++){let x=rand(i+61)*W,y=rand(i+741)*H;tree(x,y,.76+rand(i+93)*.4,i%2)}
// clearings/gathering spots
[[.22,.55,'🍄','Mushrooms'],[.40,.75,'🫐','Wild berries'],[.83,.56,'✨','Lumen flower']].forEach((a,i)=>{let x=W*a[0],y=H*a[1];ellipse(x,y+13,32,12,'#51754a55');rounded(x-34,y-25,68,43,20,'#fff5d5cc','#e8d59b');text(a[2],x,y+5,23);text(a[3],x,y+37,9,'#fdf9e8')});
}
function person(x,y,scale,kind){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ellipse(0,10,14,5,'#3b5f4355');if(kind==='mira'){// auburn-haired neighbor
ellipse(0,-12,11,12,'#a85e3d');rounded(-9,-12,18,22,8,'#e3b58f');ellipse(-2,-14,9,10,'#efc6a2');ellipse(-5,-15,1,1.3,'#49362c');ellipse(3,-15,1,1.3,'#49362c');line(-2,-8,3,-8,'#a96a5e',1);rounded(-11,1,22,12,5,'#be7182');rounded(-9,9,7,5,2,'#584b48');rounded(2,9,7,5,2,'#584b48');}else{rounded(-11,-15,22,19,8,'#d7a981');ellipse(0,-18,11,10,'#765c45');rounded(-12,-16,24,7,4,'#718b58');ellipse(-4,-15,1,1.4,'#344133');ellipse(4,-15,1,1.4,'#344133');rounded(-11,1,22,12,5,'#587c65');rounded(-9,10,7,5,2,'#574c44');rounded(2,10,7,5,2,'#574c44');}
ctx.restore()}
function drawPeople(){if(S.scene==='farm'){person(W*.62,H*.59,1.15,'player');person(W*.69,H*.48,1,'mira');if(S.friend<1){text('…',W*.69,H*.40,17,'#fff5ce')}}else{person(W*.49,H*.54,1.2,'player');}}
function drawDecor(){if(S.scene==='farm'){for(let i=0;i<10;i++){let x=W*(.06+i*.095),y=H*(.9+Math.sin(i)*.01);text(i%2?'✿':'·',x,y,13,i%2?'#f5d276':'#fff4cf')}}else{for(let i=0;i<14;i++){let x=rand(i+991)*W,y=rand(i+221)*H;ellipse(x,y,2,2,'#f8e9a5');}}}
function setToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function log(message){S.logs.unshift(`Day ${S.day}: ${message}`);S.logs=S.logs.slice(0,8)}
function spend(hours=1,energy=8){if(S.energy<energy){setToast('You are too tired. Take a little rest first.');return false}S.energy=Math.max(0,S.energy-energy);S.hunger=Math.max(0,S.hunger-5);S.hour+=hours;if(S.hour>=20){S.hour=20;setToast('It is getting late. The stars are coming out.')}updateUI();return true}
function updateUI(){document.getElementById('gold').textContent=S.gold;document.getElementById('clock').textContent=`${S.hour%12||12}:00 ${S.hour>=12?'PM':'AM'}`;document.getElementById('datePill').textContent=`Day ${S.day} · ${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(S.day-1)%7]}`;document.getElementById('energyText').textContent=`${S.energy} / 100`;document.getElementById('hungerText').textContent=`${S.hunger} / 100`;document.getElementById('moodText').textContent=`${S.mood} / 100`;document.getElementById('energyBar').style.width=S.energy+'%';document.getElementById('hungerBar').style.width=S.hunger+'%';document.getElementById('moodBar').style.width=S.mood+'%';document.getElementById('seedCount').textContent='🌱 '+S.seeds;document.getElementById('cropCount').textContent='🧺 '+S.harvest;document.getElementById('friendCount').textContent='💛 '+(S.friend?1:0);document.getElementById('wishCount').textContent=Math.min(3,S.wish)+' / 3';document.getElementById('wishText').innerHTML=S.wish>=3?'<strong>Garden beginner!</strong><br>You planted your first little patch.':'<strong>Make yourself at home.</strong><br>Plant '+Math.max(0,3-S.wish)+' more turnip seed'+(3-S.wish===1?'':'s')+' in the garden.';document.getElementById('friendRel').textContent=S.friend?'Mira · Good friend':'New neighbor · Acquaintance';document.getElementById('friendHeart').textContent='♥'.repeat(Math.min(3,Math.floor(S.relationship/2)))+'♡'.repeat(3-Math.min(3,Math.floor(S.relationship/2)));document.getElementById('weatherPill').textContent=S.rain?'🌧️ Soft rain':'☀️ Sunny';draw()}

