{label:'🌼 Give her a flower',run:()=>{if(!S.forage){setToast('Find a lumen flower in the woods first.');return}if(!spend(1,4))return;S.forage=Math.max(0,S.forage-1);S.relationship=Math.min(6,S.relationship+2);S.friend=S.relationship>=3?1:0;S.mood=Math.min(100,S.mood+10);log('You gave Mira a lumen flower.');updateUI();setToast('Mira beams. “I’ll keep it by my window.” ♥')}},
