{label:'👋 Say hello',secondary:true,run:()=>{if(!spend(1,2))return;S.relationship=Math.min(6,S.relationship+1);S.friend=S.relationship>=3?1:0;updateUI();setToast('Mira waves. “Come by anytime!”')}}])}
