function journal(){let lines=S.logs.map(x=>`<div class="logline">${x}</div>`).join('');showModal('Your journal',`<strong>Spring · Day ${S.day}</strong><br>Seeds: ${S.seeds} · Turnips picked: ${S.harvest} · Coins: ${S.gold}<br><br>${lines}`,[{label:'Lovely',secondary:true}])}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let ix=-1;if(S.scene==='farm'&&S.action==='farm')S.plots.forEach((p,i)=>{if(p.bounds&&x>=p.bounds.x&&x<=p.bounds.x+p.bounds.w&&y>=p.bounds.y&&y<=p.bounds.y+p.bounds.h)ix=i});if(ix!==hoverPlot){hoverPlot=ix;draw()}});
canvas.addEventListener('pointerleave',()=>{hoverPlot=-1;draw()});
canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(S.scene==='farm'){if(S.action==='farm'){let i=S.plots.findIndex(p=>p.bounds&&x>=p.bounds.x&&x<=p.bounds.x+p.bounds.w&&y>=p.bounds.y&&y<=p.bounds.y+p.bounds.h);if(i>=0){gardenClick(i);return}}if(S.action==='social'&&Math.abs(x/W-.69)<.13&&Math.abs(y/H-.48)<.2){openSocial();return}if(S.action==='explore'){S.scene='woods';updateUI();return}}else if(S.action==='explore')forageClick(x,y)});
document.querySelectorAll('.action').forEach(b=>b.addEventListener('click',()=>{let a=b.dataset.action;if(a==='social'&&S.action==='social'){openSocial();return}if(a==='rest'){rest();return}chooseAction(a)}));
document.querySelectorAll('.scene-switch button').forEach(b=>b.addEventListener('click',()=>{S.scene=b.dataset.scene;if(S.scene==='woods')S.action='explore';else if(S.action==='explore')S.action='farm';hoverPlot=-1;document.getElementById('hint').textContent=S.scene==='farm'?'Tap an empty bed to plant · planted beds to water or harvest':'Tap a clearing to forage for something lovely';updateUI()}));
document.getElementById('sleepBtn').addEventListener('click',endDay);document.getElementById('journalBtn').addEventListener('click',journal);document.getElementById('closeModal').addEventListener('click',closeModal);document.getElementById('modalBg').addEventListener('click',e=>{if(e.target.id==='modalBg')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
// Restore a saved farm and keep progress between visits.
try{const saved=localStorage.getItem('hearthwild-save');if(saved){const data=JSON.parse(saved);Object.assign(S,data);if(!Array.isArray(S.plots)||S.plots.length!==6)S.plots=Array.from({length:6},()=>({crop:null,water:false,age:0}))}}catch(e){}
const originalUpdate=updateUI;updateUI=function(){originalUpdate();try{localStorage.setItem('hearthwild-save',JSON.stringify(S))}catch(e){}};
resize();updateUI();
</script>
</body>
</html>

